import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';

export default function StudioLogin() {
    const navigate = useNavigate();
    const [loginData, setLoginData] = useState({
        email: '',
        password: ''
    });
    const [loading, setLoading] = useState(false);

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setLoginData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        
        if (!loginData.email || !loginData.password) {
            toast.error('Please enter both email and password');
            return;
        }

        setLoading(true);
        
        try {
            // In a real implementation, this would call your backend API
            // For now, we'll simulate a successful login
            setTimeout(() => {
                // Simulate successful login
                const userData = {
                    id: 1,
                    email: loginData.email,
                    firstName: 'Studio',
                    lastName: 'User',
                    role: 'influencer' // or 'seller'
                };
                
                localStorage.setItem('studioToken', 'simulated-token');
                localStorage.setItem('studioUser', JSON.stringify(userData));
                
                toast.success('Login successful');
                // Redirect based on user role
                if (userData.role === 'seller') {
                    navigate('/studio/seller');
                } else {
                    navigate('/studio/influencer');
                }
            }, 1000);
        } catch (error) {
            console.error('Login error:', error);
            toast.error('Login failed: ' + error.message);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="auth-page-wrapper pt-5">
            <div className="auth-one-bg-position auth-one-bg" id="auth-element">
                <div className="bg-overlay"></div>
                <div className="shape">
                    <svg xmlns="http://www.w3.org/2000/svg" version="1.1" viewBox="0 0 1440 120">
                        <path d="M 0,36 C 144,53.6 432,123.2 720,124 C 1008,124.8 1296,56.8 1440,40L1440 140L0 140z"></path>
                    </svg>
                </div>
            </div>

            <div className="auth-page-content">
                <div className="container">
                    <div className="row">
                        <div className="col-lg-12">
                            <div className="text-center mt-sm-5 mb-4 text-white-50">
                                <div>
                                    <a href="/studio" className="d-inline-block auth-logo">
                                        <img src="/assets/images/logo-light.png" alt="" height="50" />
                                    </a>
                                </div>
                                <p className="mt-3 fs-15 fw-medium">Studio Platform for Influencers and Sellers</p>
                            </div>
                        </div>
                    </div>

                    <div className="row justify-content-center">
                        <div className="col-md-8 col-lg-6 col-xl-5">
                            <div className="card mt-4">
                                <div className="card-body p-4">
                                    <div className="text-center mt-2">
                                        <h5 className="text-primary">Welcome Back !</h5>
                                        <p className="text-muted">Sign in to continue to Studio Platform.</p>
                                    </div>
                                    <div className="p-2 mt-4">
                                        <form onSubmit={handleSubmit}>
                                            <div className="mb-3">
                                                <label htmlFor="email" className="form-label">Email</label>
                                                <input
                                                    type="email"
                                                    className="form-control"
                                                    id="email"
                                                    name="email"
                                                    placeholder="Enter email"
                                                    value={loginData.email}
                                                    onChange={handleInputChange}
                                                    disabled={loading}
                                                />
                                            </div>

                                            <div className="mb-3">
                                                <div className="float-end">
                                                    <a href="#" className="text-muted">Forgot password?</a>
                                                </div>
                                                <label className="form-label" htmlFor="password">Password</label>
                                                <div className="position-relative auth-pass-inputgroup mb-3">
                                                    <input
                                                        type="password"
                                                        className="form-control pe-5 password-input"
                                                        placeholder="Enter password"
                                                        id="password"
                                                        name="password"
                                                        value={loginData.password}
                                                        onChange={handleInputChange}
                                                        disabled={loading}
                                                    />
                                                    <button className="btn btn-link position-absolute end-0 top-0 text-decoration-none text-muted password-addon" type="button">
                                                        <i className="ri-eye-fill align-middle"></i>
                                                    </button>
                                                </div>
                                            </div>

                                            <div className="form-check">
                                                <input className="form-check-input" type="checkbox" value="" id="auth-remember-check" />
                                                <label className="form-check-label" htmlFor="auth-remember-check">
                                                    Remember me
                                                </label>
                                            </div>

                                            <div className="mt-4">
                                                <button 
                                                    className="btn btn-success w-100" 
                                                    type="submit"
                                                    disabled={loading}
                                                >
                                                    {loading ? (
                                                        <>
                                                            <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                                                            Signing in...
                                                        </>
                                                    ) : (
                                                        'Sign In'
                                                    )}
                                                </button>
                                            </div>
                                        </form>
                                    </div>
                                </div>
                            </div>

                            <div className="mt-4 text-center">
                                <p className="mb-0">Don't have an account ? <a href="#" className="fw-semibold text-primary text-decoration-underline"> Signup </a> </p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}
